Script:
// Starfield - stars stream outward from the center like a hyperspace warp,
// leaving short trails as they accelerate past.
@scene fps=30 bg=#000008 trail=0.72 size=48x48

emit stars
  rate    = ${density} per 0.02..0.05s
  origin  = x:center y:center
  vel     = dir:radial speed:${speed}
  color   = pick(#ffffff,#cfe3ff,#fff0c0,#ffd9d9)
  life    = 2.5s
